// stop the application from starting. Instead:
//   1. Each candidate path in STORE_CANDIDATES is tried with a dynamic import
//      the first time a lookup runs.
//   2. If no store module is found, the handler falls back to the legacy CRM
//      export and logs a warning, so lookups keep working.
// TODO: Replace STORE_CANDIDATES with the real store module path and accessor,
// then remove the legacy fallback.
const STORE_CANDIDATES = [
  "../stores/customers.mjs",
  "../store/index.mjs",
  "../stores/index.mjs",
  "../db/customers.mjs",
  "../data/customers.mjs"
];

let storePromise;

async function loadStore() {
  for (const path of STORE_CANDIDATES) {
    try {
      const mod = await import(path);
      const store = mod.customers ?? mod.customerStore ?? mod.default ?? mod;
      const get =
        store.getCustomer ?? store.findById ?? store.get ?? store.find ?? mod.getCustomer;
      if (typeof get === "function") {
        return (id) => get.call(store, id);
      }
    } catch (err) {
      if (err?.code !== "ERR_MODULE_NOT_FOUND") throw err;
    }
  }
  console.warn(
    "customers.lookup: customer store module not found; falling back to legacy CRM export"
  );
  return null;
}

function fromLegacy(customerId) {
  const row = readExport().find((r) => r.cust_id === customerId);
  if (!row) return null;
  return {
    customerId: row.cust_id,
    name: row.full_name,
    email: row.mail,
    tier: TIERS[row.level],
    since: row.created
  };
}

function normalize(rec) {
  return {
    customerId: rec.customerId ?? rec.id ?? rec.cust_id,
    name: rec.name ?? rec.full_name,
    email: rec.email ?? rec.mail,
    tier: rec.tier ?? (rec.level !== undefined ? TIERS[rec.level] : undefined),
    since: rec.since ?? rec.createdAt ?? rec.created
  };
}

export async function lookupCustomer(input) {
  storePromise ??= loadStore();
  const getFromStore = await storePromise;

  let customer;
  if (getFromStore) {
    const rec = await getFromStore(input.customerId);
    customer = rec ? normalize(rec) : null;
  } else {
    customer = fromLegacy(input.customerId);
  }

  if (!customer) {
    throw errors.notFound(`no customer ${input.customerId}`);
  }
  return customer;
}
